public class CorrectionHistoryEntry { private String correctionId; private String actorId; private Instant correctedAt; private String reason; private String sessionId; private Map<String,Object> before; private Map<String,Object> after; public String getCorrectionId(){return correctionId;}public void setCorrectionId(String v){correctionId=v;}public String getActorId(){return actorId;}public void setActorId(String v){actorId=v;}public Instant getCorrectedAt(){return correctedAt;}public void setCorrectedAt(Instant v){correctedAt=v;}public String getReason(){return reason;}public void setReason(String v){reason=v;}public String getSessionId(){return sessionId;}public void setSessionId(String v){sessionId=v;}public Map<String,Object> getBefore(){return before;}public void setBefore(Map<String,Object> v){before=v;}public Map<String,Object> getAfter(){return after;}public void setAfter(Map<String,Object> v){after=v;} }
